import { describeBranches, type JsonSchemaOrBoolean } from "@ark/schema"
import { printable, throwParseError } from "@ark/util"
import { type, type JsonSchema } from "arktype"
import { parseArrayJsonSchema } from "./array.ts"
import { parseCommonJsonSchema } from "./common.ts"
import {
	parseAnyOfJsonSchema,
	parseCompositionJsonSchema
} from "./composition.ts"
import {
	writeJsonSchemaInsufficientKeysMessage,
	writeJsonSchemaUnresolvedRefMessage,
	writeJsonSchemaUnsupportedRefMessage,
	writeJsonSchemaUnsupportedTypeMessage
} from "./errors.ts"
import { parseNumberJsonSchema } from "./number.ts"
import { parseObjectJsonSchema } from "./object.ts"
import { JsonSchemaScope } from "./scope.ts"
import { parseStringJsonSchema } from "./string.ts"

interface ParseContext {
	readonly defs: Record<string, JsonSchema>
	readonly parsedDefs: Map<string, type.Any>
	readonly resolvingDefs: Set<string>
}

let activeContext: ParseContext | undefined

const objectKeywords = [
	"properties",
	"required",
	"patternProperties",
	"additionalProperties",
	"maxProperties",
	"minProperties",
	"propertyNames",
	"dependencies",
	"dependentRequired",
	"dependentSchemas"
] as const

const jsonSchemaTypeMatcher = type.match
	.in<Extract<JsonSchema, { type?: unknown }>>()
	.at("type")
	.match({
		"unknown[]": jsonSchema =>
			parseCompositionJsonSchema({
				anyOf: jsonSchema.type.map(t => ({ type: t as never }))
			}),
		"'array'": jsonSchema => parseArrayJsonSchema.assert(jsonSchema),
		"'boolean'|'null'": jsonSchema => type(jsonSchema.type),
		"'integer'|'number'": jsonSchema => parseNumberJsonSchema.assert(jsonSchema),
		"'object'": jsonSchema => parseObjectJsonSchema.assert(jsonSchema),
		"'string'": jsonSchema => parseStringJsonSchema.assert(jsonSchema),
		default: () => undefined
	})

const parseRef = (ref: string, ctx: ParseContext): type.Any => {
	const match = /^#\/\$defs\/([^/]+)$/.exec(ref)
	if (!match) throwParseError(writeJsonSchemaUnsupportedRefMessage())
	const name = match[1]
	const parsed = ctx.parsedDefs.get(name)
	if (parsed) return parsed
	if (!(name in ctx.defs))
		throwParseError(writeJsonSchemaUnresolvedRefMessage(ref))

	if (ctx.resolvingDefs.has(name))
		return type.unknown.narrow(value => ctx.parsedDefs.get(name)!.allows(value))

	ctx.resolvingDefs.add(name)
	try {
		const resolved = innerParseJsonSchema.assert(ctx.defs[name]) as type.Any
		ctx.parsedDefs.set(name, resolved)
		return resolved
	} finally {
		ctx.resolvingDefs.delete(name)
	}
}

const parseConditional = (jsonSchema: JsonSchema): type.Any | undefined => {
	if (!("if" in jsonSchema)) return
	const ifValidator = jsonSchemaToType(jsonSchema.if)
	const consequent = "then" in jsonSchema ? jsonSchemaToType(jsonSchema.then) : undefined
	const alternate = "else" in jsonSchema ? jsonSchemaToType(jsonSchema.else) : undefined
	if (!consequent && !alternate) return
	return type.unknown.narrow((data, ctx) => {
		const selected = ifValidator.allows(data) ? consequent : alternate
		return selected === undefined || selected.allows(data) ?
			true
		: ctx.reject({ expected: "a value valid for the matching conditional schema" })
	})
}

export const innerParseJsonSchema = JsonSchemaScope.Schema.pipe(
